import{_ as t,o as a,c as r,a2 as s}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"Cursor","description":"在 Cursor 中通过 OpenAI API Key 和 Override OpenAI Base URL 接入 Tokeness。","frontmatter":{"title":"Cursor","description":"在 Cursor 中通过 OpenAI API Key 和 Override OpenAI Base URL 接入 Tokeness。"},"headers":[],"relativePath":"integrations/cursor.md","filePath":"integrations/cursor.md","lastUpdated":1781666206000}'),o={name:"integrations/cursor.md"};function d(n,e,i,l,p,h){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="cursor" tabindex="-1">Cursor <a class="header-anchor" href="#cursor" aria-label="Permalink to &quot;Cursor&quot;">​</a></h1><p>Cursor 的自定义模型入口在不同版本中会有差异。能看到 OpenAI API Key、Override OpenAI Base URL、Add Custom Model 这类设置时，可以按 OpenAI 兼容方式接入 Tokeness。</p><p>如果当前版本没有这些入口，或者第三方模型在 Agent 工具调用中表现不稳定，改用 Cline、Claude Code、Codex CLI 或 OpenCode。</p><h2 id="接入信息" tabindex="-1">接入信息 <a class="header-anchor" href="#接入信息" aria-label="Permalink to &quot;接入信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>填写内容</th></tr></thead><tbody><tr><td>OpenAI API Key</td><td>Tokeness 控制台创建的 Key</td></tr><tr><td>Override OpenAI Base URL</td><td><code>https://n.tokeness.io/v1</code></td></tr><tr><td>Custom Model Name</td><td>Tokeness 模型广场中的完整模型名</td></tr></tbody></table><p>Cursor 这里字段名可能仍然写着 OpenAI。开启 Base URL 覆盖后，请求会发往你填写的地址。</p><h2 id="_1-准备-tokeness" tabindex="-1">1. 准备 Tokeness <a class="header-anchor" href="#_1-准备-tokeness" aria-label="Permalink to &quot;1. 准备 Tokeness&quot;">​</a></h2><p>先准备：</p><ol><li>Cursor 专用 API Key。</li><li>一个适合代码任务的模型名。</li><li>可用余额。</li></ol><p>Key 名称可以写成：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cursor-local</span></span></code></pre></div><h2 id="_2-打开-cursor-模型设置" tabindex="-1">2. 打开 Cursor 模型设置 <a class="header-anchor" href="#_2-打开-cursor-模型设置" aria-label="Permalink to &quot;2. 打开 Cursor 模型设置&quot;">​</a></h2><p>在 Cursor 中进入：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Settings -&gt; Models</span></span></code></pre></div><p>找到 API Keys、OpenAI API Key 或类似区域。</p><h2 id="_3-填写-api-key-和-base-url" tabindex="-1">3. 填写 API Key 和 Base URL <a class="header-anchor" href="#_3-填写-api-key-和-base-url" aria-label="Permalink to &quot;3. 填写 API Key 和 Base URL&quot;">​</a></h2><ol><li>开启 OpenAI API Key。</li><li>粘贴 Tokeness API Key。</li><li>开启 <code>Override OpenAI Base URL</code>。</li><li>Base URL 填写 <code>https://n.tokeness.io/v1</code>。</li><li>保存或确认。</li></ol><p>如果 Cursor 弹出确认窗口，确认它会把 OpenAI 请求发到自定义 Base URL 后再继续。</p><h2 id="_4-添加自定义模型" tabindex="-1">4. 添加自定义模型 <a class="header-anchor" href="#_4-添加自定义模型" aria-label="Permalink to &quot;4. 添加自定义模型&quot;">​</a></h2><p>在 Models 页面找到 Add Custom Model。</p><p>填写从 Tokeness 模型广场复制的模型名。添加后，关闭不需要的默认模型，避免测试时选错。</p><p>首次测试时使用短提示：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请只回复一句话，说明当前 Cursor 已经接入 Tokeness。</span></span></code></pre></div><p>然后到 Tokeness 使用日志确认请求。</p><h2 id="_5-使用范围" tabindex="-1">5. 使用范围 <a class="header-anchor" href="#_5-使用范围" aria-label="Permalink to &quot;5. 使用范围&quot;">​</a></h2><p>Cursor 的自定义 Base URL 通常适合：</p><table tabindex="0"><thead><tr><th>场景</th><th>说明</th></tr></thead><tbody><tr><td>普通聊天</td><td>先从短问题验证</td></tr><tr><td>单文件问答</td><td>控制上下文范围</td></tr><tr><td>小范围代码解释</td><td>观察模型是否能稳定回复</td></tr></tbody></table><p>对于大范围 Agent 编辑、复杂工具调用和多文件修改，不同第三方模型的兼容性可能不同。先用小任务验证，再扩大范围。</p><h2 id="_6-排查" tabindex="-1">6. 排查 <a class="header-anchor" href="#_6-排查" aria-label="Permalink to &quot;6. 排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>处理</th></tr></thead><tbody><tr><td>找不到 Override OpenAI Base URL</td><td>当前 Cursor 版本可能不支持该入口</td></tr><tr><td>401 Unauthorized</td><td>重新复制 Tokeness API Key</td></tr><tr><td>404 Not Found</td><td>Base URL 填 <code>https://n.tokeness.io/v1</code></td></tr><tr><td>model not found</td><td>自定义模型名从模型广场重新复制</td></tr><tr><td>Tokeness 无日志</td><td>当前模型没有走自定义 OpenAI 配置</td></tr><tr><td>聊天可用但 Agent 报错</td><td>该模型与 Cursor 工具调用不完全兼容，换模型或换工具</td></tr><tr><td>仍然走默认模型</td><td>关闭默认模型或在聊天侧边栏手动选择自定义模型</td></tr></tbody></table><h2 id="外部文档" tabindex="-1">外部文档 <a class="header-anchor" href="#外部文档" aria-label="Permalink to &quot;外部文档&quot;">​</a></h2><ul><li><a href="https://openrouter.ai/docs/cookbook/coding-agents/cursor-integration" target="_blank" rel="noreferrer">OpenRouter Cursor Integration</a></li><li><a href="https://docs.sambanova.ai/docs/en/integrations/cursor" target="_blank" rel="noreferrer">SambaNova Cursor Integration</a></li><li><a href="https://docs.litellm.ai/docs/tutorials/cursor_integration" target="_blank" rel="noreferrer">LiteLLM Cursor Integration</a></li></ul>',32)])])}const b=t(o,[["render",d]]);export{u as __pageData,b as default};
